const extractedData = $input.first().json.output;

const requiredFields = ['date', 'type', 'name', 'quantity', 'unit', 'person'];

let isValid = true;
let missingFields = [];

for (const field of requiredFields) {
    if (!extractedData[field] || extractedData[field] === 'N/A' || extractedData[field] === null || String(extractedData[field]).trim() === '') {
        isValid = false;
        missingFields.push(field);
    }

    if (field === 'quantity' && isValid) { 
        const quantity = Number(extractedData.quantity);
        if (isNaN(quantity) || quantity <= 0) {
            isValid = false;
            missingFields.push('quantity_numeric_positive');
        }
    }
}

if (isValid) {
    return [{ json: { isValid: true, data: extractedData } }];
} else {
    return [{ json: { isValid: false, missingFields: missingFields, originalMessage: $('Telegram Trigger').first().json.message.text } }];
}

