const reportType = $('LLM Report').first().json.output.report_type;
const reportPeriod = $('LLM Report').first().json.output.report_period;

let startDate = null;
let endDate = null;

const today = DateTime.now();

function parseSpecificPeriod(periodString) {
    const yearMonthMatch = periodString.match(/^(\d{4})-(\d{2})$/);
    if (yearMonthMatch) {
        const year = parseInt(yearMonthMatch[1]);
        const month = parseInt(yearMonthMatch[2]); 
        if (!isNaN(year) && !isNaN(month) && month >= 1 && month <= 12) {
            const date = DateTime.fromObject({ year, month });
            return { start: date.startOf('month'), end: date.endOf('month') };
        }
    }

    const months = {
        'januari': 0, 'februari': 1, 'maret': 2, 'april': 3, 'mei': 4, 'juni': 5,
        'juli': 6, 'agustus': 7, 'september': 8, 'oktober': 9, 'november': 10, 'desember': 11,
        'january': 0, 'february': 1, 'march': 2, 'april': 3, 'may': 4, 'june': 5,
        'july': 6, 'august': 7, 'september': 8, 'october': 9, 'november': 10, 'december': 11
    };

    const monthNamesRegex = Object.keys(months).join('|');

    const monthYearMatch = periodString.match(new RegExp(`(${monthNamesRegex})\\s+(\\d{4})`, 'i'));
    const dayMonthYearMatch = periodString.match(new RegExp(`(\\d{1,2})\\s+(${monthNamesRegex})\\s+(\\d{4})`, 'i'));

    if (dayMonthYearMatch) {
        const day = parseInt(dayMonthYearMatch[1]);
        const month = months[dayMonthYearMatch[2].toLowerCase()];
        const year = parseInt(dayMonthYearMatch[3]);
        if (!isNaN(day) && month !== undefined && !isNaN(year)) {
            const date = DateTime.fromObject({ year, month: month + 1, day });
            return { start: date.startOfDay(), end: date.endOfDay() };
        }
    } else if (monthYearMatch) {
        const month = months[monthYearMatch[1].toLowerCase()];
        const year = parseInt(monthYearMatch[2]);
        if (month !== undefined && !isNaN(year)) {
            const date = DateTime.fromObject({ year, month: month + 1 });
            return { start: date.startOf('month'), end: date.endOf('month') };
        }
    } else if (periodString.toLowerCase() === 'today') {
        return { start: today.startOfDay(), end: today.endOfDay() };
    } else if (periodString.toLowerCase() === 'yesterday') {
        const yesterday = today.minus({ days: 1 });
        return { start: yesterday.startOfDay(), end: yesterday.endOfDay() };
    }

    return null;
}

const specificPeriod = parseSpecificPeriod(reportPeriod);

if (specificPeriod) {
    startDate = specificPeriod.start;
    endDate = specificPeriod.end;
} else {
    switch (reportPeriod) {
        case 'this_month':
            startDate = today.startOf('month');
            endDate = today.endOf('month');
            break;
        case 'last_month':
            startDate = today.minus({ months: 1 }).startOf('month');
            endDate = today.minus({ months: 1 }).endOf('month');
            break;
        case 'this_year':
            startDate = today.startOf('year');
            endDate = today.endOf('year');
            break;
        case 'last_year':
            startDate = today.minus({ years: 1 }).startOf('year');
            endDate = today.minus({ years: 1 }).endOf('year');
            break;
        default: 
            startDate = today.startOf('month');
            endDate = today.endOf('month');
            break;
    }
}

const filterConditions = {
    filterType: reportType,
    filterStartDate: startDate ? startDate.toISODate() : null, 
    filterEndDate: endDate ? endDate.toISODate() : null,   
};

return [{ json: filterConditions }];

const items = $input.all();

if (items.length === 0) {
    return [{ json: { reportText: "Tidak ada data transaksi yang ditemukan untuk periode dan tipe yang diminta." } }];
}

let totalIncoming = 0;
let totalOutgoing = 0;
let incomingItems = {};
let outgoingItems = {};
let personsInvolved = new Set();
let uniqueItemNames = new Set();
let anomalies = [];
let reportPeriod = "";

if ( $('Prepare Filter').first().json.filterStartDate && $('Prepare Filter').first().json.filterEndDate) {
    const start = DateTime.fromISO($('Prepare Filter').first().json.filterStartDate);
    const end = DateTime.fromISO($('Prepare Filter').first().json.filterEndDate);

    if (start.hasSame(end, 'day')) {
        reportPeriod = `pada tanggal ${start.toFormat('dd MMMM yyyy')}`;
    } else if (start.hasSame(end, 'month') && start.startOf('month').equals(start) && end.endOf('month').equals(end)) {
        reportPeriod = `pada bulan ${start.toFormat('MMMM yyyy')}`;
    } else if (start.hasSame(end, 'year') && start.startOf('year').equals(start) && end.endOf('year').equals(end)) {
        reportPeriod = `pada tahun ${start.toFormat('yyyy')}`;
    } else {
        reportPeriod = `antara ${start.toFormat('dd MMMM yyyy')} hingga ${end.toFormat('dd MMMM yyyy')}`;
    }
}


for (const item of items) {
    const data = item.json;
    uniqueItemNames.add(data.name);
    personsInvolved.add(data.person);

    if (data.type === 'incoming') {
        totalIncoming += data.quantity;
        incomingItems[data.name] = (incomingItems[data.name] || 0) + data.quantity;
    } else if (data.type === 'outgoing') {
        totalOutgoing += data.quantity;
        outgoingItems[data.name] = (outgoingItems[data.name] || 0) + data.quantity;
    }

    if (data.quantity <= 0) {
        anomalies.push(`Item '${data.name}' pada ${data.date} memiliki kuantitas ${data.quantity}.`);
    }
}

let summary = `Laporan Transaksi Gudang ${reportPeriod}\n\n`;
summary += `Ringkasan:\n`;
summary += `- Jumlah total item masuk: ${totalIncoming} unit.\n`;
summary += `- Jumlah total item keluar: ${totalOutgoing} unit.\n`;
summary += `- Total jenis item unik yang tercatat: ${uniqueItemNames.size}.\n`;
summary += `- Pihak yang terlibat: ${Array.from(personsInvolved).join(', ')}.\n\n`;

summary += `Analisis Saldo:\n`;
if (totalIncoming > totalOutgoing) {
    summary += `- Stok kemungkinan bertambah sejumlah ${totalIncoming - totalOutgoing} unit (netto masuk).\n`;
} else if (totalOutgoing > totalIncoming) {
    summary += `- Stok kemungkinan berkurang sejumlah ${totalOutgoing - totalIncoming} unit (netto keluar).\n`;
} else {
    summary += `- Saldo masuk dan keluar seimbang untuk periode ini.\n`;
}
summary += `*Catatan: Analisis ini tidak mencerminkan stok awal atau akhir, hanya pergerakan selama periode laporan.*\n\n`;

summary += `Potensi Anomali:\n`;
if (anomalies.length > 0) {
    anomalies.forEach(a => summary += `- ${a}\n`);
} else {
    summary += `- Tidak ada anomali kuantitas (0 atau negatif) yang terdeteksi.\n`;
}
summary += `\n`;

summary += `Saran Praktis:\n`;
summary += `- Tinjau detail transaksi untuk item dengan kuantitas paling tinggi (masuk/keluar).\n`;
summary += `- Pastikan semua kuantitas yang dicatat positif dan valid.\n`;
summary += `- Untuk akurasi stok, disarankan untuk mengintegrasikan dengan sistem manajemen inventaris yang lebih komprehensif.\n`;

return [{ json: { reportText: summary } }];

const itemsFromGoogleSheets = $input.all();

const filterParams = $('Prepare Filter').item.json;

const reportType = filterParams.filterType;
const filterStartDate = new Date(filterParams.filterStartDate);
const filterEndDate = new Date(filterParams.filterEndDate);

const filteredItems = [];

for (const item of itemsFromGoogleSheets) {
    if (!item.json.date || item.json.date === 'N/A') {
        continue;
    }

    const itemDate = new Date(item.json.date);
    const typeMatches = (reportType === 'all' || item.json.type === reportType);
    const dateMatches = (itemDate >= filterStartDate && itemDate <= filterEndDate);

    if (typeMatches && dateMatches) {
        filteredItems.push({ json: item.json });
    }
}

return filteredItems;
